using Microsoft.Maui.Graphics; namespace FoodExpiryApp; public static class ExpiryColor { public static Color For(DateTime d){int n=(d.Date-DateTime.Today).Days; if(n<0)return Color.FromArgb("#B00035"); if(n<=3)return Color.FromArgb("#FF414D"); if(n<=7)return Color.FromArgb("#FF962E"); if(n<=14)return Color.FromArgb("#FF962E"); if(n<=21)return Color.FromArgb("#E8C928"); return Color.FromArgb("#39C879");} public static string Label(DateTime d){int n=(d.Date-DateTime.Today).Days;return n<0?$"Просрочен на {Math.Abs(n)} дн.":n==0?"Сегодня":n==1?"1 день":$"{n} дней";} }
